[Form]
public class METCustomerMDFInquiry extends FormRun
{

    private CustAccount custAccountVal;
    private InventSiteId siteIdVal;
    private InventLocationId locationIdVal;
    private CustInvoiceId custInvoiceIdVal;
    private SalesIdBase salesIdVal;
    private MetShipmentId shipmentIdVal;
    private METConsolidationMethodEDT consolidationMethodEDTVal;
    private METApplicationMethodEDT applicationMethodEDTVal;
    private METCustomerMDFInquiryTempTable customerMDFInquiryTmp;



    //#LOCALMACRO.CurrentList
    //    custAccountVal,
    //    siteIdVal,
    //    locationIdVal,
    //    custInvoiceIdVal,
    //    salesIdVal,
    //    shipmentIdVal,
    //    consolidationMethodEDTVal,
    //    applicationMethodEDTVal
    //#ENDMACRO




}

private void initParameters()
{
    xSysLastValue::getLast(this);

    CustAccount.text(custAccountVal);
    Site.text(siteIdVal);
    Warehouse.text(locationIdVal);
    TaxInvoice.text(custInvoiceIdVal);
    SalesOrders.text(salesIdVal);
    ShipmentId.text(shipmentIdVal);
    ConsolidationMethod.text(enum2Str(consolidationMethodEDTVal));
    ApplicationMethod.text(enum2Str(applicationMethodEDTVal));

}

public void lookup()
{
    Query query = new Query();
    QueryBuildDataSource queryBuildDataSource, qbds;
    QueryBuildRange queryBuildRange;

    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(custTable), this);

    sysTableLookup.addLookupField(fieldNum(CustTable, AccountNum));
    sysTableLookup.addLookupField(fieldNum(CustTable, CustGroup));
    sysTableLookup.addLookupField(fieldNum(CustTable, Party), false);
    queryBuildDataSource = query.addDataSource(tableNum(CustTable));
    qbds = queryBuildDataSource.addDataSource(tableNum(DirPartyTable));
    qbds.joinMode(JoinMode::InnerJoin);
    qbds.addLink(fieldNum(CustTable, Party), fieldNum(DirPartyTable, RecId));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();

}

public boolean modified()
{
    boolean ret;
    ret = super();

    CustName.text(CustTable::find(CustAccount.valueStr()).Name());

    MetCustomerMdfTable metCustomerMdfTbl;

    //metCustomerMdfTable = MetCustomerMdfTable::find(CustAccount.valueStr(), Site.valueStr(), Warehouse.valueStr());
    select firstOnly metCustomerMdfTbl
        where metCustomerMdfTbl.CustAccount == CustAccount.valueStr();

    if (metCustomerMdfTbl.RecId !=0)
    { 

        Site.text(metCustomerMdfTbl.InventSiteId);
        Warehouse.text(metCustomerMdfTbl.InventLocationId);
        ApplicationMethod.text(enum2Str(metCustomerMdfTbl.ApplicationMethodEDT));
        ConsolidationMethod.text(enum2Str(metCustomerMdfTbl.ConsolidationMethodEDT));
    }

    return ret;
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventSite), Site);
    Query lookupQuery = new Query();

    // Build the query
    QueryBuildDataSource siteIdDS = lookupQuery.addDataSource(tableNum(InventSite));
    sysTableLookup.addLookupField(fieldNum(InventSite, SiteId));
    sysTableLookup.addLookupField(fieldNum(InventSite, Name));
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation), Warehouse);
    Query lookupQuery = new Query();

    // Add InventLocation as the main data source
    QueryBuildDataSource locationDS = lookupQuery.addDataSource(tableNum(InventLocation));
    locationDS.addRange(fieldNum(InventLocation, InventSiteId)).value(queryValue(Site.valueStr()));
    sysTableLookup.addLookupField(fieldNum(InventLocation, InventLocationId));
    sysTableLookup.addLookupField(fieldNum(InventLocation, Name));
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public boolean modified()
{
    boolean ret;
    ret = super();
    MetCustomerMdfTable metCustomerMdfTabl;

    info(strFmt("Warehouse modified%1, %2, %3", CustAccount.valueStr(), Site.valueStr(), Warehouse.valueStr()));

    select firstOnly metCustomerMdfTabl
        where metCustomerMdfTabl.CustAccount == CustAccount.valueStr()
           && metCustomerMdfTabl.InventSiteId == Site.valueStr()
           && metCustomerMdfTabl.InventLocationId == Warehouse.valueStr();

    if (metCustomerMdfTabl.RecId !=0)
    {
        ApplicationMethod.text(enum2Str(metCustomerMdfTabl.ApplicationMethodEDT));
        ConsolidationMethod.text(enum2Str(metCustomerMdfTabl.ConsolidationMethodEDT));
    }

    return ret;
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(CustInvoiceJour), TaxInvoice);
    Query lookupQuery = new Query();

    // Add CustInvoiceJour as primary data source
    QueryBuildDataSource invoiceDS = lookupQuery.addDataSource(tableNum(CustInvoiceJour));

    // Join SalesTable to filter by customer, site, warehouse, and status
    QueryBuildDataSource salesDS = invoiceDS.addDataSource(tableNum(SalesTable));
    salesDS.relations(true); // CustInvoiceJour.SalesId → SalesTable.SalesId
    salesDS.joinMode(JoinMode::InnerJoin);

    // Filter: Only show invoices where sales order status is Invoiced
    salesDS.addRange(fieldNum(SalesTable, SalesStatus)).value(queryValue(SalesStatus::Invoiced));

    // Filter by selected customer
    if (CustAccount.valueStr())
    {
        salesDS.addRange(fieldNum(SalesTable, CustAccount)).value(queryValue(CustAccount.valueStr()));
    }

    // Filter by selected site
    if (Site.valueStr())
    {
        salesDS.addRange(fieldNum(SalesTable, InventSiteId)).value(queryValue(Site.valueStr()));
    }

    // Filter by selected warehouse
    if (Warehouse.valueStr())
    {
        salesDS.addRange(fieldNum(SalesTable, InventLocationId)).value(queryValue(Warehouse.valueStr()));
    }

    // Add fields to display in the lookup
    sysTableLookup.addLookupField(fieldNum(CustInvoiceJour, InvoiceId));
    sysTableLookup.addLookupField(fieldNum(CustInvoiceJour, InvoiceDate));
    sysTableLookup.addLookupField(fieldNum(CustInvoiceJour, SalesId));
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public boolean modified()
{
    boolean ret;
    ret = super();

    CustInvoiceJour invoiceJour;
    // Get selected invoice
    select firstOnly invoiceJour
        where invoiceJour.InvoiceId == TaxInvoice.valueStr();

    SalesOrders.text(invoiceJour.SalesId);

    METSalesOrderShipmentLoadHeader shipment;

    if (invoiceJour)
    {
        SalesId salesId = invoiceJour.SalesId;
        SalesTable salesTable = SalesTable::find(salesId);

        // Corrected: Match shipment.SalesId to salesTable.SalesId
        select firstOnly shipment
        where shipment.SiteId == salesTable.InventSiteId
        && shipment.CustAccount == salesTable.CustAccount
        && shipment.Warehouse == salesTable.InventLocationId;

        if (shipment)
        {
            ShipmentId.text(shipment.ShipmentId);
        }
    }

    return ret;
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(SalesTable), SalesOrders);
    Query lookupQuery = new Query();

    // Add SalesTable as the main data source
    QueryBuildDataSource salesDS = lookupQuery.addDataSource(tableNum(SalesTable));

    // Filter: Only show sales orders with status = Invoiced
    salesDS.addRange(fieldNum(SalesTable, SalesStatus)).value(queryValue(SalesStatus::Invoiced));

    // Add fields to display in the lookup
    sysTableLookup.addLookupField(fieldNum(SalesTable, SalesId));
    sysTableLookup.addLookupField(fieldNum(SalesTable, CustAccount));
    sysTableLookup.addLookupField(fieldNum(SalesTable, DeliveryDate));
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(
        tableNum(METSALESORDERSHIPMENTLOADLINES),ShipmentId);

    Query lookupQuery = new Query();

    QueryBuildDataSource shipmentDS = lookupQuery.addDataSource(tableNum(METSALESORDERSHIPMENTLOADLINES));

    shipmentDS.addGroupByField(fieldNum(METSALESORDERSHIPMENTLOADLINES, ShipmentId));

    if (SalesOrders.valueStr())
    {
        shipmentDS.addRange(fieldNum(METSALESORDERSHIPMENTLOADLINES, OrderNum)).value(queryValue(SalesOrders.valueStr()));
    }

    sysTableLookup.addLookupField(fieldNum(METSALESORDERSHIPMENTLOADLINES, ShipmentId));

    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public void clicked()
{
    super();
    int insertedCount = this.populateRecords();

    METCustomerMDFInquiryTempTable_DS.executeQuery();

    if (insertedCount == 0)
    {
        info("No matching MDF setup records found for the selected filters.");
    }
    else
    {
        info(strFmt("%1 record(s) loaded into the inquiry results.", insertedCount));
    }

}

/// <summary>
///
/// </summary>
public int populateRecords()
{
    MetCustomerMdfTable mdfTable;
    MetCustomerMdfSetupTable setupTable;
    METCustomerMDFInquiryTempTable tempTable;

    METCustomerMDFInquiryTempTable.linkPhysicalTableInstance(tempTable);

    // Clear previous results
    delete_from tempTable;

    // Capture selected values
    //str customerId        = CustAccount.valueStr();
    //str siteId            = Site.valueStr();
    //str warehouseId       = Warehouse.valueStr();
    //str taxInvoice        = TaxInvoice.valueStr();
    //str shipmentId        = ShipmentId.valueStr();
    //str salesOrder        = SalesOrders.valueStr();
    //METApplicationMethodEDT appMethod = ApplicationMethod.valueStr();
    //METConsolidationMethodEDT consolidationMethod = ConsolidationMethod.valueStr();
    // Capture selected enum values
    //METApplicationMethodEDT appMethod = str2Enum(enumNum(METApplicationMethodEDT), ApplicationMethod.valueStr());
    //METConsolidationMethodEDT consolMethod = str2Enum(enumNum(METConsolidationMethodEDT), ConsolidationMethod.valueStr());


    int insertedCount = 0;
    ttsbegin;
    // Query and populate temp table
    while select setupTable
    where setupTable.RefRecId != 0
    join mdfTable
    where mdfTable.RecId == setupTable.RefRecId &&
            mdfTable.CustAccount == CustAccount.valueStr() &&
            mdfTable.InventSiteId == Site.valueStr() &&
            mdfTable.InventLocationId == Warehouse.valueStr()
    {
        tempTable.Description           = setupTable.Description;
        tempTable.DeliveryChargeType    = setupTable.DeliveryChargeType;
        tempTable.MinimumDeliveryFee    = setupTable.MinimumDeliveryFee;
        tempTable.InvoiceId             = TaxInvoice.valueStr();
        tempTable.ThresholdValue        = setupTable.ThresholdValue;
        tempTable.ItemScope             = setupTable.ItemScope;
        tempTable.ShipmentId            = ShipmentId.valueStr();
        tempTable.SalesId               = SalesOrders.valueStr();

        tempTable.insert();
        insertedCount++;
    }
    ttscommit;

    return insertedCount;

}
